import{_ as a,a as i,o as t,M as o}from"./chunks/framework.DYNaguLt.js";const m=JSON.parse('{"title":"Privacy Policy","description":"","frontmatter":{"wordCount":305,"readingTime":"2 minute read"},"headers":[],"relativePath":"privacy/index.md","filePath":"privacy/index.md"}'),n={name:"privacy/index.md"};function r(s,e,c,d,l,p){return t(),i("div",null,e[0]||(e[0]=[o('<h1 id="privacy-policy" tabindex="-1">Privacy Policy <a class="header-anchor" href="#privacy-policy" aria-label="Permalink to “Privacy Policy”">​</a></h1><hr><p>Last updated: March 24, 2026</p><p>This Privacy Policy describes how we collect, use, disclose, and retain personal data for the blog (the &quot;Site&quot;) operated from the European Union. The Site does not set cookies. The Site collects only website traffic data under legitimate interests (Article 6(1)(f) GDPR), such as page visits and referring URLs. This Policy explains what data we collect, why, and how long we keep it.</p><h2 id="what-we-collect" tabindex="-1">What we collect <a class="header-anchor" href="#what-we-collect" aria-label="Permalink to “What we collect”">​</a></h2><p>Automatically collected traffic data (no cookies): page visits/pages viewed, timestamps, referring URLs, aggregate page view counts, and basic technical details necessary to deliver content (e.g., browser type, operating system, and anonymized IP-derived region). We do not collect or store full IP addresses; where IPs are processed, they are anonymized/pseudonymized on collection.</p><h2 id="lawful-basis-for-processing" tabindex="-1">Lawful basis for processing <a class="header-anchor" href="#lawful-basis-for-processing" aria-label="Permalink to “Lawful basis for processing”">​</a></h2><p>Legitimate interests (Article 6(1)(f) GDPR): to operate and improve the Site, analyze and understand usage patterns, maintain security, prevent abuse, and measure content performance.</p><h2 id="purposes-of-processing" tabindex="-1">Purposes of processing <a class="header-anchor" href="#purposes-of-processing" aria-label="Permalink to “Purposes of processing”">​</a></h2><ul><li><strong>Analytics and site performance</strong>: measure page visits, popular pages, and referring sources to improve content and user experience.</li><li><strong>Security and abuse prevention</strong>: detect and respond to malicious activity.</li></ul><h2 id="no-cookies-and-no-tracking-scripts" tabindex="-1">No cookies and no tracking scripts <a class="header-anchor" href="#no-cookies-and-no-tracking-scripts" aria-label="Permalink to “No cookies and no tracking scripts”">​</a></h2><p>The Site does not set client-side cookies, does not use local storage for tracking, and does not load third-party tracking scripts that create persistent identifiers. Any analytics are performed on server-side aggregated or anonymized data collection only.</p><h2 id="data-minimization-and-anonymization" tabindex="-1">Data minimization and anonymization <a class="header-anchor" href="#data-minimization-and-anonymization" aria-label="Permalink to “Data minimization and anonymization”">​</a></h2><p>We collect the minimum data necessary for the stated purposes. Where possible, data is aggregated or anonymized so it no longer constitutes personal data under GDPR (for example, removing or truncating IP address information promptly). Raw identifying details are not retained.</p><h2 id="changes-to-this-policy" tabindex="-1">Changes to this policy <a class="header-anchor" href="#changes-to-this-policy" aria-label="Permalink to “Changes to this policy”">​</a></h2><p>We may update this Policy.</p><h2 id="acknowledgement" tabindex="-1">Acknowledgement <a class="header-anchor" href="#acknowledgement" aria-label="Permalink to “Acknowledgement”">​</a></h2><p>By using the Site you acknowledge that you have read and understood this Policy.</p>',18)]))}const g=a(n,[["render",r]]);export{m as __pageData,g as default};
